local IsServiceChecker = {}
IsServiceChecker.__index = IsServiceChecker

function IsServiceChecker.new(services)
	local self = setmetatable({}, IsServiceChecker)
	self._services = services
	return self
end

function IsServiceChecker:IsService(serviceType)
	if serviceType.IsGenericTypeDefinition then
		return false
	end

	local match = self:findLastService(serviceType)

	if not match and serviceType.IsGenericType then
		local genericDefine = serviceType:GetGenericTypeDefinition()
		match = self:findLastService(genericDefine)
	end

	if match then
		return true
	elseif self:isAssignableToEnumerable(serviceType) and serviceType.IsGenericType then
		return true
	end

	return false
end

function IsServiceChecker:findLastService(serviceType)
	for i = #self._services, 1, -1 do
		if self._services[i].ServiceType == serviceType then
			return self._services[i]
		end
	end
	return nil
end

function IsServiceChecker:isAssignableToEnumerable(serviceType)
	-- 在Lua中，我们需要一个更具体的实现来检查是否可以分配给IEnumerable
	-- 这里只是一个简单的占位实现
	return type(serviceType) == "table"
end

return IsServiceChecker
